/**
 * Runtime config from Vite env vars (frontend/.env.local, generated by `make frontend-env`
 * from CDK stack outputs). None of these are secrets: they're public IDs and URLs.
 */
export interface AppConfig {
  userPoolId: string;
  userPoolClientId: string;
  cognitoDomain: string;
  apiUrl: string;
}

export function loadConfig(env: Record<string, string | undefined> = import.meta.env): AppConfig {
  const required = {
    userPoolId: env.VITE_USER_POOL_ID,
    userPoolClientId: env.VITE_USER_POOL_CLIENT_ID,
    cognitoDomain: env.VITE_COGNITO_DOMAIN,
    apiUrl: env.VITE_API_URL,
  };
  const missing = Object.entries(required)
    .filter(([, value]) => !value)
    .map(([key]) => key);
  if (missing.length > 0) {
    throw new Error(`Missing config: ${missing.join(", ")}. Run \`make frontend-env\` after deploying.`);
  }
  return required as AppConfig;
}
